result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "globwalk.py", "content": "#!/usr/bin/env python3
"""globwalk.py -- print filesystem paths matching an extended glob pattern.

Supported syntax:
    **      recursive descent (zero or more path segments)
    *       any run of characters within a single path segment
    ?       any single character within a single path segment
    {a,b}   single-level brace alternation

Hidden files/directories (names starting with '.') are matched only when
the corresponding pattern segment itself starts with a dot.  A bare '**'
segment traverses hidden directories like pathlib.Path.glob does.

The glob module is intentionally not used.
"""

import os
import re
import sys


def expand_braces(pattern):
    """Expand single-level brace groups into a list of concrete patterns."""
    i = pattern.find('{')
    if i == -1:
        return [pattern]
    j = pattern.find('}', i + 1)
    if j == -1:
        return [pattern]  # unmatched '{' -> literal
    inner = pattern[i + 1:j]
    if '{' in inner:
        raise ValueError('nested braces are not supported: %r' % pattern)
    alternatives = inner.split(',') if inner else ['']
    expanded = []
    for alt in alternatives:
        expanded.extend(expand_braces(pattern[:i] + alt + pattern[j + 1:]))
    return expanded


def _compile_segment(segment):
    """Compile one non-'**' glob segment into a regex for a file name."""
    parts = []
    for ch in segment:
        if ch == '*':
            parts.append('.*')
        elif ch == '?':
            parts.append('.')
        else:
            parts.append(re.escape(ch))
    return re.compile(''.join(parts))


def _scandir(path):
    try:
        return list(os.scandir(path))
    except (FileNotFoundError, NotADirectoryError, PermissionError):
        return []


def _match(segments, regexes, path, results):
    if not segments:
        results.append(path)
        return
    head = segments[0]
    if head == '**':
        # Match zero segments here ...
        _match(segments[1:], regexes[1:], path, results)
        # ... or descend one level and let '**' consume more.
        for entry in _scandir(path):
            _match(segments, regexes, entry.path, results)
        return
    rx = regexes[0] if regexes is not None else _compile_segment(head)
    allow_hidden = head.startswith('.')
    for entry in _scandir(path):
        name = entry.name
        if name.startswith('.') and not allow_hidden:
            continue
        if rx.fullmatch(name):
            _match(segments[1:], regexes[1:], entry.path, results)


def match(root='.', pattern='*'):
    """Return a sorted list of paths under *root* matching *pattern*.

    Results are relative POSIX-style strings ('/' separators).
    """
    pattern = pattern.replace(os.sep, '/') if os.sep != '/' else pattern
    segments = [s for s in pattern.split('/') if s not in ('', '.')]
    regexes = [_compile_segment(s) if s != '**' else None for s in segments]
    results = []
    root = str(root)
    _match(segments, regexes, root, results)
    return sorted(
        os.path.relpath(p, root).replace(os.sep, '/') for p in results)


def main(argv=None):
    argv = list(sys.argv if argv is None else argv)
    if len(argv) != 2:
        print('usage: globwalk.py PATTERN', file=sys.stderr)
        return 2
    try:
        patterns = expand_braces(argv[1])
    except ValueError as exc:
        print('globwalk: %s' % exc, file=sys.stderr)
        return 2
    seen = set()
    for pat in patterns:
        for hit in match('.', pat):
            if hit not in seen:
                seen.add(hit)
                print(hit)
    return 0


if __name__ == '__main__':
    sys.exit(main())
